    'tagName',
  ],
  'github_get_pr': ['workspace', 'repository', 'pullRequestId'],
  'github_get_pr_activities': ['workspace', 'repository', 'pullRequestId'],
  'github_get_pr_conversations': ['workspace', 'repository', 'pullRequestId'],
