    },
    'jira_link_issues': {
      'sourceKey': ['sourceKey', 'sourceId'],
      'anotherKey': ['anotherKey', 'targetId'],
    },
    'jira_attach_file_to_ticket': {
      'key': ['key', 'ticketKey', 'id'],
    },
    'ado_add_work_item_comment': {
      'comment': ['comment', 'text', 'body'],
    },
    'ado_list_work_items': {
      'wiql': ['wiql', 'jql', 'query', 'searchQueryJQL'],
